from copy import deepcopy


def combine_sensors(devices, channels_by_device, samples_by_device):
    if not all(isinstance(x, list) for x in (devices, channels_by_device, samples_by_device)):
        raise ValueError("inputs must be lists")
    if len(devices) != len(channels_by_device) or len(devices) != len(samples_by_device):
        raise ValueError("length mismatch")
    result = []
    names = set()
    for device, channels, samples in zip(devices, channels_by_device, samples_by_device):
        if not isinstance(device, dict) or set(device) != {"name"} or not isinstance(device["name"], str) or not device["name"] or device["name"] in names:
            raise ValueError("invalid device")
        names.add(device["name"])
        if not isinstance(channels, list) or not isinstance(samples, dict):
            raise ValueError("invalid device data")
        codes = set()
        output_channels = []
        for channel in channels:
            if not isinstance(channel, dict) or set(channel) != {"code", "label"}:
                raise ValueError("invalid channel")
            code = channel["code"]
            if not isinstance(code, str) or not code or code in codes or not isinstance(channel["label"], str):
                raise ValueError("invalid channel")
            codes.add(code)
            output_channels.append({"code": code, "label": channel["label"], "value": samples.get(code)})
        if set(samples) != codes:
            raise ValueError("sample mismatch")
        result.append({"name": device["name"], "channels": output_channels})
    return deepcopy(result)
```

